/**
 * Register scroll effect resolver function.
 *
 * The function should be a pure function.
 *
 * @param {string} name
 * @param {Function} resolver
 */
export declare const add: (name: any, resolver: any) => void;
/**
 * Return a scroll effect resolver function.
 *
 * @param name
 * @returns {Function}
 */
export declare const get: (name: any) => any;
